#include <sys/socket.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>

int main() {
    int sv[2];  // Socket pair file descriptors

    // Create a pair of connected UNIX domain sockets
    // AF_UNIX: Unix domain, SOCK_STREAM: reliable byte stream
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == -1) {
        perror("socketpair");
        return 1;
    }

    // sv[0] and sv[1] are now connected
    // Data written to sv[0] can be read from sv[1] and vice versa

    pid_t pid = fork();

    if (pid == 0) {  // Child process
        close(sv[0]);  // Child uses sv[1]

        char msg[] = "Hello from child";
        write(sv[1], msg, strlen(msg) + 1);

        char buf[100];
        read(sv[1], buf, sizeof(buf));
        printf("Child received: %s\n", buf);

        close(sv[1]);
    } else {  // Parent process
        close(sv[1]);  // Parent uses sv[0]

        char buf[100];
        read(sv[0], buf, sizeof(buf));
        printf("Parent received: %s\n", buf);

        char msg[] = "Hello from parent";
        write(sv[0], msg, strlen(msg) + 1);

        close(sv[0]);
    }

    return 0;
}
